SELECT
    p_req.session_id                            AS from_session_id,
    ai.session_id                                AS to_session_id,
    MIN(COALESCE(ai.started_at, ai.created_at)) AS first_ts,
    MAX(COALESCE(ai.started_at, ai.created_at)) AS last_ts,
    COUNT(*)                                     AS edge_count
FROM agents.instances ai
